import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const p="/img/surplus-deficit-logic.svg",e="/img/surplus-surplus-logic.svg",u=JSON.parse('{"title":"小学数学趣题巧解：盈亏问题的“分配”艺术","description":"“分果果，排排坐。”盈亏问题是小学奥数中极具趣味性和逻辑性的题型。如何通过“总差额”和“单差额”快速锁定答案？本文通过生动的图解，带你玩转盈亏问题。","frontmatter":{"title":"小学数学趣题巧解：盈亏问题的“分配”艺术","date":"2026-02-08T17:00:00.000Z","categories":["数学"],"tags":["小学数学","趣题巧解","盈亏问题","奥数入门"],"description":"“分果果，排排坐。”盈亏问题是小学奥数中极具趣味性和逻辑性的题型。如何通过“总差额”和“单差额”快速锁定答案？本文通过生动的图解，带你玩转盈亏问题。","cover":"/img/surplus-deficit-logic.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-clever-solutions-surplus-deficit.md","filePath":"posts/primary-math-clever-solutions-surplus-deficit.md","lastUpdated":null}'),l={name:"posts/primary-math-clever-solutions-surplus-deficit.md"};function o(r,a,i,c,h,d){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="小学数学趣题巧解-盈亏问题的-分配-艺术" tabindex="-1">小学数学趣题巧解：盈亏问题的“分配”艺术 <a class="header-anchor" href="#小学数学趣题巧解-盈亏问题的-分配-艺术" aria-label="Permalink to &quot;小学数学趣题巧解：盈亏问题的“分配”艺术&quot;">​</a></h1><p>小朋友们，你们遇到过这样的问题吗？</p><p>“老师给同学们分苹果，如果每人分 3 个，就多出 5 个；如果每人分 5 个，就少 3 个。请问有多少个小朋友？多少个苹果？”</p><p>这种在分配物体时，由于分配方案不同而出现的“多了（盈）”或“少了（亏）”的问题，在数学上被称为**“盈亏问题”**。</p><p>看起来一头雾水？别担心，只要掌握了**“差额分析法”**，你就能瞬间破解！</p><hr><h2 id="一、-核心思维-为什么会有-盈-和-亏" tabindex="-1">一、 核心思维：为什么会有“盈”和“亏”？ <a class="header-anchor" href="#一、-核心思维-为什么会有-盈-和-亏" aria-label="Permalink to &quot;一、 核心思维：为什么会有“盈”和“亏”？&quot;">​</a></h2><p>盈亏问题的关键在于：<strong>总量的变化是由每个人分得的数量变化引起的。</strong></p><p>我们来看上面的例子：</p><ul><li><strong>第一次</strong>：每人 3 个 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 剩 5 个。</li><li><strong>第二次</strong>：每人 5 个 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 缺 3 个。</li></ul><p>从第一次到第二次，每个人<strong>多拿了</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">5 - 3 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 个。 就是因为每人多拿了这 2 个，才把原来多出的 5 个用掉了，而且还倒欠了 3 个。</p><p>所以，这增加的“每人 2 个”，一共填补了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">5 + 3 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span> 个空缺。</p><p><img src="'+p+'" alt="盈亏问题逻辑图解"></p><hr><h2 id="二、-万能公式-三步锁定答案" tabindex="-1">二、 万能公式：三步锁定答案 <a class="header-anchor" href="#二、-万能公式-三步锁定答案" aria-label="Permalink to &quot;二、 万能公式：三步锁定答案&quot;">​</a></h2><p>解盈亏问题，我们要用到两个“差”：</p><ol><li><strong>单差</strong>：两次分配方案中，每个人分得数量的差。</li><li><strong>总差</strong>：两次分配结果的总变动额。</li></ol><h3 id="核心公式" tabindex="-1">核心公式： <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式：&quot;">​</a></h3><blockquote><p><strong>人数 = 总差 ÷ 单差</strong></p></blockquote><h3 id="如何计算-总差" tabindex="-1">如何计算“总差”？ <a class="header-anchor" href="#如何计算-总差" aria-label="Permalink to &quot;如何计算“总差”？&quot;">​</a></h3><p>这里有一个口诀，一定要记牢：</p><ul><li><strong>一盈一亏</strong>：总差 = 盈 + 亏 （相加）</li><li><strong>两次都盈</strong>：总差 = 大盈 - 小盈 （相减）</li><li><strong>两次都亏</strong>：总差 = 大亏 - 小亏 （相减）</li></ul><hr><h2 id="三、-经典模型解析" tabindex="-1">三、 经典模型解析 <a class="header-anchor" href="#三、-经典模型解析" aria-label="Permalink to &quot;三、 经典模型解析&quot;">​</a></h2><h3 id="模型-1-一盈一亏-最经典" tabindex="-1">模型 1：一盈一亏（最经典） <a class="header-anchor" href="#模型-1-一盈一亏-最经典" aria-label="Permalink to &quot;模型 1：一盈一亏（最经典）&quot;">​</a></h3><p><strong>【例题 1】</strong> 小朋友分糖果，每人分 4 块多 10 块；每人分 6 块少 2 块。有多少个小朋友？多少块糖？ <strong>解析</strong>：</p><ol><li><strong>找单差</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">6 - 4 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span>（块/人）。</li><li><strong>找总差</strong>：一盈一亏用加法，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">10 + 2 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>（块）。</li><li><strong>求人数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">12 \\div 2 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>（人）。</li><li><strong>求总量</strong>：用方案 1 验算，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>×</mo><mn>4</mn><mo>+</mo><mn>1</mn><mn>0</mn><mo>=</mo><mn>3</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">6 \\times 4 + 10 = 34</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">4</span></span></span></span>（块）。 <strong>答案</strong>：6 个小朋友，34 块糖。</li></ol><h3 id="模型-2-两盈或两亏" tabindex="-1">模型 2：两盈或两亏 <a class="header-anchor" href="#模型-2-两盈或两亏" aria-label="Permalink to &quot;模型 2：两盈或两亏&quot;">​</a></h3><p><strong>【例题 2】</strong> 士兵搬砖，每人搬 8 块，剩 14 块；每人搬 9 块，剩 2 块。有多少个士兵？多少块砖？</p><p><img src="'+e+'" alt="两盈问题图解"></p><p><strong>解析</strong>：</p><ol><li><strong>找单差</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo>−</mo><mn>8</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">9 - 8 = 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mbin">−</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span>（块/人）。</li><li><strong>找总差</strong>：两次都盈用减法，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>4</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">14 - 2 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>（块）。</li><li><strong>求人数</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>÷</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">12 \\div 1 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">÷</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>（人）。</li><li><strong>求总量</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>×</mo><mn>8</mn><mo>+</mo><mn>1</mn><mn>4</mn><mo>=</mo><mn>1</mn><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">12 \\times 8 + 14 = 110</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>（块）。 <strong>答案</strong>：12 个士兵，110 块砖。</li></ol><hr><h2 id="四、-避坑指南-审题要细" tabindex="-1">四、 避坑指南：审题要细 <a class="header-anchor" href="#四、-避坑指南-审题要细" aria-label="Permalink to &quot;四、 避坑指南：审题要细&quot;">​</a></h2><p>在盈亏问题的变式题中，经常会出现“隐藏的方案”。</p><p>比如：“如果每人分 4 个，还剩 10 个；如果其中 2 人不分，其余人每人分 6 个，正好分完。” 这时候，我们要把方案 2 转化一下： 2 人不分，相当于<strong>少了</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">2 \\times 6 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span> 个。 所以方案 2 实际上是：“每人分 6 个，少 12 个”。</p><hr><h2 id="五、-闯关练习" tabindex="-1">五、 闯关练习 <a class="header-anchor" href="#五、-闯关练习" aria-label="Permalink to &quot;五、 闯关练习&quot;">​</a></h2><ol><li><strong>(基础关)</strong> 老师给美术小组发画纸。每人发 5 张，多出 13 张；每人发 8 张，就只剩 1 张了。美术小组有多少人？一共有多少张画纸？</li><li><strong>(进阶关)</strong> 一群猴子分桃子。如果每只猴子分 5 个，还剩 7 个；如果每只猴子分 7 个，最后一只猴子只分到 3 个。请问有多少只猴子？多少个桃子？</li><li><strong>(挑战关)</strong> 学校组织划船。如果每条船坐 10 人，还有 9 人在岸上；如果每条船坐 12 人，则正好空出一条船。共有多少条船？多少名学生？</li></ol><hr><p><em>总结：盈亏问题其实就是“分配不均”带来的差额补偿。只要找准了单差和总差，所有的难题都会迎刃而解！</em></p>',41)])])}const x=s(l,[["render",o]]);export{u as __pageData,x as default};
